package php

import (
	_ "embed"
	"strings"
)

// builtins.txt is generated by //gazelle/php:builtins_dump under the pinned
// PHP: the lowercased classes, interfaces, traits, functions and constants it
// provides without user code.
//
//go:embed builtins.txt
var builtinsText string

var builtinSet = func() map[string]struct{} {
	set := make(map[string]struct{})
	for _, line := range strings.Split(builtinsText, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			set[line] = struct{}{}
		}
	}
	return set
}()

// IsStdLib reports whether name is a global class, function or constant of the
// pinned PHP. Namespaced names never match: the builtins live in the global
// namespace, and a reference inside a namespace only reaches them through a
// leading backslash or a use clause, which the parser resolves to the bare name.
func IsStdLib(name string) bool {
	if name == "" || strings.Contains(name, `\`) {
		return false
	}
	_, ok := builtinSet[strings.ToLower(name)]
	return ok
}
